SELECT length('phi'), upper('phi'), lower('phi'), substr('phi', 0, 0), instr('phi', 'tau'), replace('phi', 'a', ''), trim('phi'), ltrim('phi', 'ab'), hex('phi'), quote('phi'), unicode('phi'), 'phi' LIKE 'a%', 'phi' GLOB '*[a-m]*', char(88, 925), 'phi' || 'tau', 'phi' < 'tau', 'phi' = 'tau' COLLATE NOCASE;
